#include <stdio.h>

// 函数声明
int factorial(int num);

int main() {    
    int x = 5;

    printf("The factorial of %d is %d\n", x, factorial(x));

    return 0;
}

// 函数定义
int factorial(int num) {

    if (num == 1)  /* 退出条件 */
        return (1);
    else
        return (num * factorial(num - 1));
}

